// Stock AF target banks under an EMULATOR-ONLY injected pose.
// Orientation Linked is changed with native menu keys. NVRAM off. No overlay.
// Subject Detect is not opened and not enabled.
// Do not edit this file after it has run.
// Usage: node26 work/scripts/bank_s5.mjs om-emu
import { createHash } from 'node:crypto';
import { existsSync, readFileSync, statSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { attachPose, POSES } from './pose.mjs';

const [checkout] = process.argv.slice(2);
if (!checkout) {
  process.stderr.write('usage: node26 work/scripts/bank_s5.mjs om-emu\n');
  process.exit(2);
}
process.env.OM_EMU_MODEL = 'E147';
process.env.OM_EMU_NVRAM = 'off';
const use = (p) => import(pathToFileURL(resolve(checkout, 'emu', p)).href);
const IMAGE_BASE = 0x60021020;
const dis = (address) => (0x50000000 + address - IMAGE_BASE) >>> 0;
const GETTER = 0x60063380;
const TEN = 0xa33ca384;
const OUT = resolve('work/out/bank-s5.jsonl');
let DEADLINE = Date.now() + 12 * 60 * 1000;
const KEYS = [
  [0x5962, 8], [0x88b2, 8], [0x1dd1, 16], [0x1db1, 8], [0x1dc1, 8],
  [0x99a1, 8], [0x9a41, 8], [0x99d2, 8], [0xdfa1, 8], [0xe91, 8],
];
const WATCH = new Set(KEYS.map(([k]) => k));

const { loadNand, loadImage, loadBlock, createHash: fwHash } = await use('checks/lib/env.mjs');
const { Player } = await use('src/lab/player.mjs');
const { apply_uiin_layout } = await use('src/lab/play.mjs');
const { PLAYER_PARSER } = await use('scenarios/session_replay.mjs');
const { MenuWalk } = await use('src/lab/menuwalk.mjs');
const { write_png } = await use('checks/lib/png.mjs');
const { words_to_rgb } = await use('src/lab/display.mjs');

const IMPORT_RE = /(?:from\s+|import\s*\(\s*|import\s+)['"]([^'"]+)['"]/g;
function resolveSpec(fromFile, spec) {
  if (!spec.startsWith('.')) return null;
  const base = resolve(dirname(fromFile), spec);
  for (const candidate of [base, base + '.mjs', base + '.js', join(base, 'index.mjs'), join(base, 'index.js')]) {
    if (existsSync(candidate) && statSync(candidate).isFile()) return candidate;
  }
  return null;
}
const seeds = [
  resolve(checkout, 'emu/checks/lib/env.mjs'),
  resolve(checkout, 'emu/src/lab/player.mjs'),
  resolve(checkout, 'emu/src/lab/play.mjs'),
  resolve(checkout, 'emu/scenarios/session_replay.mjs'),
  resolve(checkout, 'emu/src/lab/menuwalk.mjs'),
  resolve(checkout, 'emu/checks/lib/png.mjs'),
  resolve(checkout, 'emu/src/lab/display.mjs'),
  fileURLToPath(import.meta.url),
];
const seen = new Map();
const queue = [...seeds];
while (queue.length) {
  const file = queue.pop();
  if (!file || seen.has(file) || !existsSync(file)) continue;
  const data = readFileSync(file);
  seen.set(file, { sha256: createHash('sha256').update(data).digest('hex'), bytes: data.length });
  IMPORT_RE.lastIndex = 0;
  const text = data.toString('utf8');
  let match;
  while ((match = IMPORT_RE.exec(text))) {
    const next = resolveSpec(file, match[1]);
    if (next) queue.push(next);
  }
}
writeFileSync(resolve('work/out/bank-s5-imports.json'), JSON.stringify(
  [...seen.entries()].map(([path, meta]) => ({ path: path.replaceAll('\\', '/'), sha256: meta.sha256, bytes: meta.bytes })).sort((a, b) => a.path.localeCompare(b.path)),
  null, 2,
) + '\n');

const lines = [];
const log = (row) => {
  lines.push(JSON.stringify(row));
  writeFileSync(OUT, lines.join('\n') + '\n');
  console.log(JSON.stringify({
    step: row.step, screen: row.screen, highlight: row.highlight,
    area: row.enables && row.enables.area, point: row.enables && row.enables.point,
    raw: row.pose && row.pose.raw, exif: row.pose && row.pose.exif, error: row.error || null,
  }));
};
const msg = (e) => String(e && e.stack ? e.stack : e).slice(0, 600);

const fw = { rom: loadImage(), resBlock: loadBlock(), summary: null, changed: [] };
apply_uiin_layout(fw.rom);
const pl = new Player(
  { ...PLAYER_PARSER, no_browser: true, idle: 'off', a15: 'on', out: '<out>', no_wait_on_error: true },
  {
    ...fw, nand: loadNand(), createHash: fwHash, wallClock: () => performance.now() / 1000,
    machine: { coverage: { mark() {}, stub() {} } }, patch: fw.summary, patchRanges: fw.changed, loaded: 'on',
  },
);
pl.camapp_components = true;
pl.camapp_native_tra = true;

let failed = null;
try {
  log({ step: 'open', poses: POSES });
  pl.open_session();
  DEADLINE = Date.now() + 9 * 60 * 1000;
  const s = pl.session;
  const l = s.lab;
  const pose = attachPose(l);
  let reading = false;
  const gets = [];
  l.observe(dis(GETTER), (_lab, r) => {
    if (reading) return;
    const key = r.d0 & 0xffff;
    if (!WATCH.has(key) || gets.length > 500) return;
    gets.push({ key, index: r.d1 & 0xffff, from: r.mdr >>> 0 });
  }, 'obs-bank-getter');
  const readKey = (key, index) => {
    reading = true;
    try { return l.call(dis(GETTER), { d0: key, d1: index, a0: 0 }, null, null, 200000).d0 & 0xffff; }
    finally { reading = false; }
  };
  const cells = () => {
    const out = {};
    for (const [key, n] of KEYS) out[key.toString(16)] = Array.from({ length: n }, (_, i) => readKey(key, i));
    out.ten = [...l.sim.read(TEN, 10)];
    return out;
  };
  const enables = () => ({ area: readKey(0x1db1, 0), point: readKey(0x1dc1, 0) });
  const idle = (ms) => {
    const to = l.lab_time() + ms * 1e6;
    while (l.lab_time() < to && Date.now() < DEADLINE) s.idle_slice(Math.min(to, l.lab_time() + 50e6));
  };
  const key = (k, d) => { s.key(k, d); s.camapp.pump(); };
  const press = (k) => { key(k, 'down'); idle(80); key(k, 'up'); idle(350); };
  const walk = new MenuWalk({ press, frame: () => s.frame('boundary'), draws: () => l.draw_log }, { limit: 40 });
  let shotN = 0;
  const viewOf = () => {
    let screen = null;
    try { screen = s.screen(); } catch { /* not ready */ }
    try {
      const scr = walk.read();
      const texts = scr.texts.map((t) => t.text);
      let highlight = null;
      for (const t of scr.texts) {
        try {
          const listed = walk.list(scr, t);
          if (listed && listed.cursor != null && listed.rows[listed.cursor]) { highlight = listed.rows[listed.cursor].text; break; }
        } catch { /* not a list */ }
      }
      return { screen, texts, highlight, frame: scr.frame };
    } catch (e) {
      let frame = null;
      try { frame = s.frame('boundary'); } catch { /* none */ }
      return { screen, texts: [], highlight: null, frame, error: msg(e) };
    }
  };
  const snap = (step, extra = {}) => {
    const view = viewOf();
    let file = null;
    if (view.frame) {
      file = resolve('work/out/bank-s5-' + String(shotN).padStart(3, '0') + '-' + step.replace(/[^a-z0-9-]+/gi, '_') + '.png');
      shotN += 1;
      write_png(file, view.frame[0], view.frame[1], words_to_rgb(view.frame[2]));
    }
    const row = {
      step, screen: view.screen, texts: view.texts, highlight: view.highlight, textError: view.error || null,
      screenshot: file ? file.split(/[/\\]/).pop() : null,
      enables: enables(), cells: cells(), gets: gets.splice(0, gets.length),
      pose: extra.pose || null, diff: extra.diff || null, note: extra.note || null,
    };
    log(row);
    return row;
  };
  const timeLeft = () => Date.now() < DEADLINE;
  const has = (row, needle) => (row.texts || []).some((t) => String(t).includes(needle));
  const escapeShooting = () => {
    for (let i = 0; i < 8 && timeLeft(); i++) {
      if (s.screen() === 'shooting') return true;
      press('menu');
    }
    return s.screen() === 'shooting';
  };
  const applyPose = (name) => {
    pose.setPose(name);
    const fired = pose.deliver();
    idle(400);
    const read = pose.read();
    return { name, fired, read };
  };

  idle(600);
  const start = applyPose('landscape');
  log({ step: 'producers', pose: start.read, fired: start.fired, counts: pose.counts });

  press('menu');
  let tab = null;
  for (let i = 0; i < 28 && timeLeft(); i++) {
    tab = viewOf();
    if ((tab.texts || []).some((t) => t.includes('Orientation Linked'))) break;
    press('left');
  }
  log({ step: 'tab', screen: tab && tab.screen, texts: tab && tab.texts, highlight: tab && tab.highlight });
  for (let i = 0; i < 8 && timeLeft(); i++) {
    const cur = viewOf();
    if (cur.highlight && cur.highlight.includes('Orientation Linked')) break;
    press('down');
  }
  press('ok');
  const page = snap('orient-page');
  const turned = [];
  for (let row = 0; row < 2 && timeLeft(); row++) {
    const before = enables();
    press('right');
    const afterRight = snap('row-' + row + '-right', { note: 'before ' + JSON.stringify(before) });
    if (afterRight.enables.area !== before.area || afterRight.enables.point !== before.point) {
      turned.push({ row, key: 'right', enables: afterRight.enables });
    } else {
      press('ok');
      const sub = snap('row-' + row + '-ok');
      const onText = (sub.texts || []).find((t) => /(^|[^A-Za-z])On([^A-Za-z]|$)/.test(t));
      if (onText) {
        for (let j = 0; j < 4 && timeLeft(); j++) {
          const cur = viewOf();
          if (cur.highlight && /(^|[^A-Za-z])On([^A-Za-z]|$)/.test(cur.highlight)) break;
          press('down');
        }
        press('ok');
        snap('row-' + row + '-on');
      } else {
        press('down');
        press('ok');
        snap('row-' + row + '-down-ok');
      }
      if (s.screen() !== 'menu' || !has(viewOf(), 'AF Target')) press('menu');
    }
    if (row === 0) press('down');
  }
  const linked = snap('linked-state', { note: JSON.stringify(turned) });
  escapeShooting();

  const measure = (tag, name) => {
    if (!timeLeft()) return;
    if (s.screen() !== 'shooting') escapeShooting();
    const applied = applyPose(name);
    const before = cells();
    gets.splice(0, gets.length);
    press('up');
    const opened = snap(tag + '-' + name + '-open', { pose: applied.read });
    press('right');
    const moved = snap(tag + '-' + name + '-right', { pose: pose.read() });
    const changed = (a, b) => {
      const out = {};
      for (const k of Object.keys(a)) {
        const av = JSON.stringify(a[k]);
        const bv = JSON.stringify(b[k]);
        if (av !== bv) out[k] = { before: a[k], after: b[k] };
      }
      return out;
    };
    log({
      step: tag + '-' + name + '-diff',
      pose: applied.read,
      openDiff: changed(before, opened.cells),
      moveDiff: changed(opened.cells, moved.cells),
      gets: moved.gets,
    });
    press('menu');
    escapeShooting();
  };

  for (const name of ['landscape', 'exif6', 'exif8']) measure('on', name);

  if (timeLeft()) {
    press('menu');
    for (let i = 0; i < 12 && timeLeft(); i++) {
      if ((viewOf().texts || []).some((t) => t.includes('Orientation Linked'))) break;
      press('left');
    }
    for (let i = 0; i < 8 && timeLeft(); i++) {
      const cur = viewOf();
      if (cur.highlight && cur.highlight.includes('Orientation Linked')) break;
      press('down');
    }
    press('ok');
    for (let row = 0; row < 2 && timeLeft(); row++) {
      const before = enables();
      press('right');
      const after = enables();
      log({ step: 'off-try-' + row, enables: after, note: JSON.stringify(before) });
      if (after.area === 0 && after.point === 0 && (before.area !== 0 || before.point !== 0)) break;
      if (row === 0) press('down');
    }
    snap('linked-off');
    escapeShooting();
    for (const name of ['landscape', 'exif6', 'exif8']) measure('off', name);
  }
  log({ step: 'done', counts: pose.counts, publishes: pose.publishes });
} catch (e) {
  failed = e;
  log({ step: 'fail', error: msg(e) });
} finally {
  try { if (pl.session) pl.close_session(); } catch { /* already closed */ }
}
if (failed) process.exitCode = 1;
